<?php
function student_permission_ensure_table($con){ @mysqli_query($con,"CREATE TABLE IF NOT EXISTS tblstudentpermissionrequest (request_id int unsigned NOT NULL AUTO_INCREMENT, student_id varchar(30) NOT NULL, teacher_id varchar(30) NOT NULL, permission_type varchar(60) NOT NULL, reason text NOT NULL, start_datetime datetime NOT NULL, end_datetime datetime NOT NULL, status enum('pending','approved','declined') NOT NULL DEFAULT 'pending', decision_note varchar(500) DEFAULT NULL, decided_at datetime DEFAULT NULL, created_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(request_id), KEY student_status(student_id,status), KEY teacher_status(teacher_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"); }
function student_permission_escape($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function student_permission_teacher($con,$student){ $s=mysqli_real_escape_string($con,$student); $q="SELECT ct.userid FROM tbltermregistry tr INNER JOIN tblclassteacher ct ON ct.classid=tr.class_entryid AND ct.batchid=tr.batchid AND ct.termname=tr.termname AND ct.status='active' WHERE tr.userid='$s' AND tr.status='active' ORDER BY tr.datetimeentry DESC LIMIT 1"; $r=@mysqli_query($con,$q); $row=$r?mysqli_fetch_assoc($r):null; return $row?$row['userid']:''; }
?>
